static const int fontcjk_count=151;

/* 二分查 16x16 中文字形，返回16个uint16行或NULL */
static const uint16_t* cjk_lookup(uint32_t cp){
  int lo=0,hi=fontcjk_count-1;
  while(lo<=hi){ int m=(lo+hi)/2; uint32_t c=fontcjk[m].cp;
    if(c==cp) return fontcjk[m].rows; else if(c<cp) lo=m+1; else hi=m-1; }
  return 0;
}
